INSERT INTO `ls_distribution_config` (`id`, `key`, `value`, `create_time`, `update_time`, `delete_time`) VALUES (7, 'protocol_content', '<p>本分销协议（以下简称\"协议\"）由以下各方（以下简称\"双方\"）于协商一致的基础上签署：</p><p>电商商城（以下简称\"平台\"）：<br/>公司名称：<br/>注册地址：<br/>联系方式：</p><p>分销商（以下简称\"分销商\"）：<br/>个人/公司名称：<br/>注册地址：<br/>联系方式：</p><p>背景与目的：<br/>平台是一家电商商城，提供线上销售平台和服务，希望通过与分销商合作，扩大产品的销售渠道和市场份额。分销商具备销售渠道和客户资源，愿意成为平台的合作伙伴，进行产品的分销和销售。</p><p>鉴于上述情况，双方达成以下协议：</p><ol><li><p>分销权与产品：<br/>1.1 平台授予分销商在平台上销售以下产品的分销权：</p><ul><li>[具体产品名称和描述]<br/>1.2 分销商有权在平台上展示和销售上述产品，并享有相应的销售利润。</li></ul></li><li><p>分销商的权利和义务：<br/>2.1 分销商有责任积极推广和销售平台上的产品，并提供客户服务和售后支持。<br/>2.2 分销商应遵守平台的规定和政策，包括但不限于产品展示、价格设定、售后处理等方面的规定。<br/>2.3 分销商应确保所提供的信息准确无误，并保护平台的商业机密和客户信息不被泄露或滥用。</p></li><li><p>平台的权利和义务：<br/>3.1 平台将提供一定程度的产品支持，包括但不限于产品信息、库存管理、物流配送等方面的支持。<br/>3.2 平台有权对分销商的销售行为进行监督和管理，并根据平台政策对违规行为进行处理，包括但不限于警告、暂停合作、终止合作等措施。</p></li><li><p>价格和利润分配：<br/>4.1 平台将根据协议约定的价格体系向分销商提供产品，并与分销商约定利润分配机制。<br/>4.2 分销商应按照约定的价格销售产品，并按照约定的利润分配机制获取相应的销售利润。</p></li><li><p>保密条款：<br/>5.1 双方应保护对方的商业机密信息，包括但不限于产品信息、价格策略、销售数据等。<br/>5.2 未经对方书面同意，任何一方不得向第三方披露对方的商业机密信息。</p></li><li><p>协议的生效和终止：<br/>6.1 本协议自双方签署之日起生效，有效期为 [有效期限]。<br/>6.2 双方如需终止协议，应提前 [提前通知期限] 书面通知对方。</p></li><li><p>争议解决：<br/>7.1 双方如发生争议，应通过友好协商解决；协商不成的，应提交有管辖权的法院解决。</p></li></ol><p>请双方代表确认并签署本分销协议。</p><p>平台代表（签名）：______________ 日期：______________<br/>分销商代表（签名）：______________ 日期：______________</p>', 1700041157, 1700041157, NULL);
