INSERT INTO `ls_config` (`type`, `name`, `value`, `create_time`, `update_time`) VALUES ('shop', 'service_agreement_content', '<h3><p><span style=\"font-weight: normal;\">一、微信小程序或APP或网站服务条款的确认和接纳本微信小程序或APP或网站（以下统称本站）的各项电子服务的所有权和运作权归本平台。本站提供的服务将完全按照其发布的服务条款和操作规则严格执行。用户同意所有服务条款并完成注册程序，才能成为本站的正式用户。用户确认：本协议条款是处理双方权利义务的约定，除非违反国家强制性法律，否则始终有效。在下订单的同时，您也同时承认了您拥有购买这些产品的权利能力和行为能力，并且将您对您在订单中提供的所有信息的真实性负责。<br/>二、服务简介本站运用自己的操作系统通过国际互联网络为用户提供网络服务。同时，用户必须：(1)自行配备上网的所需设备，包括个人电脑、调制解调器或其它必备上网装置。(2)自行负担个人上网所支付的与此服务有关的电话费用、网络费用。基于本站所提供的网络服务的重要性，用户应同意(1)提供详尽、准确的个人资料。(2)不断更新注册资料，符合及时、详尽、准确的要求。本站保证不公开用户的真实姓名、地址、电子邮箱和联系电话等用户信息， 除以下情况外：(1)用户授权本站透露这些信息。(2)相应的法律及程序要求本站提供用户的个人资料。<br/><br/>三、价格和数量本站将尽最大努力保证您所购商品与网站上公布的价格一致。产品的价格和可获性都在本站上指明，这类信息将随时更改。您所订购的商品，如果发生缺货，您有权取消定单。<br/><br/>四、送货本站将会把产品送到您所指定的送货地址。所有在本站上列出的送货时间为参考时间，参考时间的计算是根据库存状况、正常的处理过程和送货时间、送货地点的基础上估计得出的。 请清楚准确地填写您的真实姓名、送货地址及联系方式。因如下情况造成订单延迟或无法配送等，本站将无法承担迟延配送的责任：(1)客户提供错误信息和不详细的地址；(2)货物送达无人签收，由此造成的重复配送所产生的费用及相关的后果。(3)不可抗力，例如：自然灾害、交通戒严、突发战争等。<br/><br/>五、服务条款的修改本站将可能不定期的修改本用户协议的有关条款，一旦条款及服务内容产生变动，本站将会在重要页面上提示修改内容。<br/><br/>六、用户隐私制度尊重用户个人隐私是本站的一项基本政策。所以，作为对以上第二条注册资料分析的补充，本站一定不会在未经合法用户授权时公开、编辑或透露其注册资料及保存在本站中的非公开内容。<br/><br/>七、用户的帐号，密码和安全性用户一旦注册成功，成为本站的合法用户，将得到一个密码和用户名。您可随时根据指示改变您的密码。用户需谨慎合理的保存、使用用户名和密码。用户若发现任何非法使用用户帐号或存在安全漏洞的情况，请立即通知本站和向公安机关报案。<br/><br/>八、对用户信息的存储和限制如果用户违背了国家法律法规规定或本协议约定，本站有视具体情形中止或终止对其提供网络服务的权利。<br/><br/>九、用户管理本协议依据国家相关法律法规规章制定，用户同意严格遵守以下条款：(1)从中国境内向外传输技术性资料时必须符合中国有关法规。(2) 不利用本站从事非法活动。(3)不干扰或混乱网络服务。(4)遵守所有使用网络服务的网络协议、规定、程序和惯例。用户须承诺不传输任何违法犯罪的、骚扰性的、中伤他人的、辱骂性的、恐吓性的、伤害性的、庸俗的，淫秽的、不文明的等信息资料；不传输损害国家社会公共利益和涉及国家安全的信息资料；不传输教唆他人从事本条所述行为的信息资料。未经许可而非法进入其它电脑系统是禁止的。若用户的行为不符合以上提到的服务条款，本站将作出独立判断立即取消用户服务帐号。用户需对自己在网上的行为承担法律责任。用户若在本站上散布和传播反动、色情或其它违反国家法律的信息，本站的系统记录有可能作为用户违反法律的证据。<br/><br/>十、通告所有发给用户的通告都可通过重要页面的公告或电子邮件或常规的信件传送。用户协议条款的修改、服务变更、或其它重要事件的通告都会以此形式进行。<br/><br/>十一、网络服务内容的所有权本站定义的网络服务内容包括：文字、软件、声音、图片、录象、图表、广告中的全部内容；电子邮件的全部内容；本站为用户提供的其它信息。所有这些内容受版权、商标、标签和其它财产所有权法律的保护。所以，用户只能在本站和广告商授权下才能使用这些内容，而不能擅自复制、再造这些内容、或创造与内容有关的派生产品。本站所有的文章版权归原文作者和本站共同所有，任何人需要转载本站的文章，必须征得原文作者和本站授权。<br/><br/>十二、责任限制如因不可抗力或其它本站无法控制的原因使本站销售系统崩溃或无法正常使用导致网上交易无法完成或丢失有关的信息、记录等本站会尽可能合理地协助处理善后事宜，并尽最大努力使客户免受损失。<br/><br/>十三、法律管辖和适用本协议的订立、执行和解释及争议的解决均应适用中国法律。如发生本站服务条款与中国法律相抵触时，则这些条款将完全按法律规定重新解释，而其它有效条款继续有效。如双方就本协议内容或其执行发生任何争议，双方应尽力友好协商解决；协商不成时，任何一方均可向人民法院提起诉讼。</span></p></h3>', 1700128634, 1700128634);
INSERT INTO `ls_config` (`type`, `name`, `value`, `create_time`, `update_time`) VALUES ('shop', 'privacy_policy_name', '隐私协议', 1700128634, 1700128634);
